import React, { useState, useRef } from 'react';
import { GoogleGenAI } from "@google/genai";

const VeoGenerator: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [preview, setPreview] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [videoUrl, setVideoUrl] = useState<string | null>(null);
  const [statusMessage, setStatusMessage] = useState("");
  const [error, setError] = useState<string | null>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (selectedFile) {
      setFile(selectedFile);
      const reader = new FileReader();
      reader.onloadend = () => setPreview(reader.result as string);
      reader.readAsDataURL(selectedFile);
    }
  };

  const generateVideo = async () => {
    if (!preview) return;
    setLoading(true);
    setError(null);
    setVideoUrl(null);
    setStatusMessage("Checking API Access...");

    try {
      // Mandatorily check if key is selected for Veo models
      const hasKey = await (window as any).aistudio.hasSelectedApiKey();
      if (!hasKey) {
        await (window as any).aistudio.openSelectKey();
      }

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      setStatusMessage("Starting Video Generation (Veo-3.1)... This may take a few minutes.");

      const base64Data = preview.split(',')[1];

      let operation = await ai.models.generateVideos({
        model: 'veo-3.1-fast-generate-preview',
        prompt: 'Animate this character in a dynamic, cinematic way with subtle camera movement.',
        image: {
          imageBytes: base64Data,
          mimeType: file?.type || 'image/png',
        },
        config: {
          numberOfVideos: 1,
          resolution: '720p',
          aspectRatio: '16:9'
        }
      });

      // Poll for completion
      while (!operation.done) {
        setStatusMessage(`Generating... Still working on it. Thanks for your patience!`);
        await new Promise(resolve => setTimeout(resolve, 10000));
        operation = await ai.operations.getVideosOperation({ operation: operation });
      }

      if (operation.response?.generatedVideos?.[0]?.video?.uri) {
        const downloadLink = operation.response.generatedVideos[0].video.uri;
        const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
        const blob = await response.blob();
        const url = URL.createObjectURL(blob);
        setVideoUrl(url);
        setStatusMessage("Success! Your animation is ready.");
      } else {
        throw new Error("Failed to retrieve generated video URL.");
      }
    } catch (err: any) {
      console.error(err);
      if (err.message?.includes("Requested entity was not found")) {
        setError("API Key error. Please re-select your key.");
        await (window as any).aistudio.openSelectKey();
      } else {
        setError(err.message || "An error occurred during video generation.");
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="py-24 px-6 max-w-7xl mx-auto">
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-16 items-center">
        <div className="space-y-8">
          <header>
            <span className="bg-accent px-3 py-1 text-primary font-black neubrutalism-shadow border-4 border-black mb-4 inline-block uppercase tracking-widest text-sm">
              Creative Lab
            </span>
            <h2 className="text-4xl md:text-6xl font-black text-primary tracking-tighter uppercase leading-none">
              BIẾN ẢNH THÀNH <span className="block italic underline decoration-accent">KHOẢNH KHẮC</span>
            </h2>
          </header>

          <p className="text-lg font-bold text-slate-700 uppercase">
            Sử dụng công nghệ AI Veo 3.1 mới nhất để mang hơi thở cuộc sống vào những bức ảnh tĩnh của tôi. Thử nghiệm với sự sáng tạo vô hạn.
          </p>

          <div className="p-8 bg-white border-4 border-black neubrutalism-shadow-blue space-y-6">
            <div className="relative border-4 border-dashed border-primary p-12 text-center cursor-pointer hover:bg-slate-50 transition-colors">
              <input 
                type="file" 
                onChange={handleFileChange} 
                className="absolute inset-0 opacity-0 cursor-pointer" 
                accept="image/*"
              />
              <span className="material-symbols-outlined text-5xl text-primary mb-4 block">upload_file</span>
              <p className="font-black text-primary uppercase">Tải ảnh lên để bắt đầu</p>
              <p className="text-xs text-gray-400 mt-2">JPG, PNG (Max 5MB)</p>
            </div>

            {preview && (
              <div className="mt-4 animate-in fade-in duration-500">
                <p className="text-xs font-black mb-2 uppercase text-gray-500">Preview:</p>
                <div className="w-full aspect-video bg-slate-100 border-4 border-black overflow-hidden">
                  <img src={preview} alt="Preview" className="w-full h-full object-cover" />
                </div>
              </div>
            )}

            <button 
              onClick={generateVideo}
              disabled={loading || !preview}
              className={`w-full py-5 font-display font-black text-xl uppercase border-4 border-black transition-all ${
                loading || !preview 
                ? 'bg-gray-200 text-gray-400 cursor-not-allowed' 
                : 'bg-primary text-accent hover:translate-x-1 hover:translate-y-1 hover:shadow-none neubrutalism-shadow'
              }`}
            >
              {loading ? 'Đang xử lý...' : 'Tạo Video Animation'}
            </button>

            {statusMessage && !error && (
              <p className="text-center font-bold text-primary animate-pulse text-sm uppercase">{statusMessage}</p>
            )}

            {error && (
              <div className="p-4 bg-red-100 border-2 border-red-500 text-red-600 text-sm font-bold uppercase text-center">
                {error}
              </div>
            )}
          </div>
        </div>

        <div className="relative">
          <div className="absolute -top-10 -right-10 w-32 h-32 bg-accent rounded-full border-4 border-black flex items-center justify-center neubrutalism-shadow z-20 animate-bounce">
            <span className="material-symbols-outlined text-5xl text-primary">movie</span>
          </div>

          <div className="aspect-[9/16] lg:aspect-video bg-dark border-8 border-black neubrutalism-shadow-yellow overflow-hidden flex items-center justify-center group">
            {videoUrl ? (
              <video 
                src={videoUrl} 
                className="w-full h-full object-cover" 
                controls 
                autoPlay 
                loop 
              />
            ) : (
              <div className="text-center p-12">
                <span className="material-symbols-outlined text-8xl text-accent/20 mb-6 group-hover:scale-110 transition-transform">play_circle</span>
                <p className="text-accent text-xl font-black italic tracking-widest uppercase">Video của bạn sẽ xuất hiện ở đây</p>
                <p className="text-gray-500 text-xs mt-2 uppercase">VEO 3.1 FAST GENERATE PREVIEW</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

